1	-- 污水排放在线监测与限排联动：H2 内存库（MODE=MySQL）建表脚本
2	-- 仅保存合成数据；时间列均为 Asia/Shanghai 本地时间，由应用时钟写入。
3	
4	CREATE TABLE IF NOT EXISTS discharge_outlet (
5	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    outlet_code     VARCHAR(64)  NOT NULL,
7	    outlet_name     VARCHAR(128) NOT NULL,
8	    status          VARCHAR(32)  NOT NULL,
9	    daily_limit     DECIMAL(18,4) NOT NULL,
10	    hourly_limit    DECIMAL(18,4) NOT NULL,
11	    limit_unit      VARCHAR(32)  NOT NULL DEFAULT 'mg/L',
12	    created_at      TIMESTAMP    NOT NULL,
13	    updated_at      TIMESTAMP    NOT NULL,
14	    archived_at     TIMESTAMP,
15	    CONSTRAINT uk_outlet_code UNIQUE (outlet_code)
16	);
17	COMMENT ON COLUMN discharge_outlet.status IS '排口状态：REGISTERED 许可登记 / MONITORING 在线监测 / RESTRICTED 限排执行中 / ARCHIVED 已归档（终态）';
18	COMMENT ON COLUMN discharge_outlet.daily_limit IS '许可日均值限值，单位 mg/L，含本值达标（日均值恰等于限值判达标）';
19	COMMENT ON COLUMN discharge_outlet.hourly_limit IS '许可小时均值限值，单位 mg/L，含本值达标';
20	
21	CREATE TABLE IF NOT EXISTS monitor_reading (
22	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
23	    outlet_code     VARCHAR(64)  NOT NULL,
24	    period_type     VARCHAR(8)   NOT NULL,
25	    period_start    TIMESTAMP    NOT NULL,
26	    avg_value       DECIMAL(18,4) NOT NULL,
27	    sample_count    INT          NOT NULL DEFAULT 1,
28	    created_at      TIMESTAMP    NOT NULL,
29	    CONSTRAINT uk_reading_period UNIQUE (outlet_code, period_type, period_start)
30	);
31	COMMENT ON COLUMN monitor_reading.period_type IS '时段类型：HOUR 小时均值 / DAY 日均值';
32	COMMENT ON COLUMN monitor_reading.avg_value IS '时段平均浓度，单位 mg/L（合成数据）';
33	COMMENT ON COLUMN monitor_reading.period_start IS '时段起始时刻（整点）；排口＋时段类型＋时段起始唯一，用于读数去重';
34	
35	CREATE TABLE IF NOT EXISTS exceedance_mark (
36	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
37	    outlet_code     VARCHAR(64)  NOT NULL,
38	    mark_type       VARCHAR(16)  NOT NULL,
39	    period_start    TIMESTAMP    NOT NULL,
40	    period_end      TIMESTAMP    NOT NULL,
41	    limit_value     DECIMAL(18,4) NOT NULL,
42	    actual_value    DECIMAL(18,4) NOT NULL,
43	    chain_index     INT          NOT NULL DEFAULT 0,
44	    request_id      VARCHAR(80),
45	    status          VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
46	    created_at      TIMESTAMP    NOT NULL,
47	    CONSTRAINT uk_mark_period UNIQUE (outlet_code, mark_type, period_start)
48	);
49	COMMENT ON COLUMN exceedance_mark.mark_type IS '超标类型：DAILY_AVG 日均值超标 / HOURLY_AVG 小时均值超标';
50	COMMENT ON COLUMN exceedance_mark.chain_index IS '小时超标连续链序号，1=连续第 1 次；连续第 3 次触发限排令';
51	COMMENT ON COLUMN exceedance_mark.request_id IS '幂等请求号：日均值评价由调用方提供，小时链标记为自动派生号';
52	COMMENT ON COLUMN exceedance_mark.status IS '标记状态：ACTIVE 生效中 / RESOLVED 随限排令复测合格关闭';
53	
54	CREATE TABLE IF NOT EXISTS restriction_order (
55	    id                      BIGINT AUTO_INCREMENT PRIMARY KEY,
56	    order_no                VARCHAR(64)  NOT NULL,
57	    outlet_code             VARCHAR(64)  NOT NULL,
58	    status                  VARCHAR(32)  NOT NULL,
59	    trigger_period_start    TIMESTAMP,
60	    frozen_total_qty        DECIMAL(18,4),
61	    issued_at               TIMESTAMP    NOT NULL,
62	    confirm_deadline        TIMESTAMP    NOT NULL,
63	    confirmed_at            TIMESTAMP,
64	    escalated_at            TIMESTAMP,
65	    escalate_reason         VARCHAR(255),
66	    retest_period_start     TIMESTAMP,
67	    retest_period_end       TIMESTAMP,
68	    retest_value            DECIMAL(18,4),
69	    release_request_id      VARCHAR(80),
70	    closed_at               TIMESTAMP,
71	    active_slot             VARCHAR(64),
72	    created_at              TIMESTAMP    NOT NULL,
73	    updated_at              TIMESTAMP    NOT NULL,
74	    CONSTRAINT uk_order_no UNIQUE (order_no),
75	    CONSTRAINT uk_active_order UNIQUE (outlet_code, active_slot),
76	    CONSTRAINT chk_order_frozen CHECK (status = 'PENDING_CONFIRM' OR frozen_total_qty IS NOT NULL)
77	);
78	COMMENT ON COLUMN restriction_order.status IS '限排令状态：PENDING_CONFIRM 待确认 / ACTIVE 已确认执行 / ESCALATED 超期未确认升级并联动限产 / CLOSED 复测合格关闭';
79	COMMENT ON COLUMN restriction_order.frozen_total_qty IS '限排生效时冻结的排放总量基数（合成单位：mg/L·小时累计），与状态转执行同事务写入，为空表示基数未定';
80	COMMENT ON COLUMN restriction_order.confirm_deadline IS '确认执行截止时刻=下达时刻+2 小时，恰满 2 小时仍未确认即升级';
81	COMMENT ON COLUMN restriction_order.active_slot IS '执行中占槽=排口编码，关闭后置空；配合唯一约束保证同一排口同时刻仅一个执行中限排令';
82	
83	CREATE TABLE IF NOT EXISTS production_cut (
84	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
85	    order_no        VARCHAR(64)  NOT NULL,
86	    outlet_code     VARCHAR(64)  NOT NULL,
87	    cut_ratio       DECIMAL(5,2) NOT NULL,
88	    reason          VARCHAR(255) NOT NULL,
89	    status          VARCHAR(16)  NOT NULL DEFAULT 'EFFECTIVE',
90	    created_at      TIMESTAMP    NOT NULL,
91	    CONSTRAINT uk_cut_order UNIQUE (order_no)
92	);
93	COMMENT ON COLUMN production_cut.cut_ratio IS '联动限产比例，0.30 表示限产 30%';
94	
95	CREATE TABLE IF NOT EXISTS data_gap (
96	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
97	    outlet_code     VARCHAR(64)  NOT NULL,
98	    gap_start       TIMESTAMP    NOT NULL,
99	    gap_end         TIMESTAMP    NOT NULL,
100	    gap_minutes     INT          NOT NULL,
101	    status          VARCHAR(16)  NOT NULL,
102	    supervised_at   TIMESTAMP,
103	    created_at      TIMESTAMP    NOT NULL,
104	    CONSTRAINT uk_gap_range UNIQUE (outlet_code, gap_start, gap_end)
105	);
106	COMMENT ON COLUMN data_gap.gap_minutes IS '连续缺失时长（分钟）；仅当严格大于 120 分钟才建缺失督办，恰 120 分钟不标记';
107	COMMENT ON COLUMN data_gap.status IS '缺失状态：SUPERVISED 已督办 / RESOLVED 已恢复';
108	
109	CREATE TABLE IF NOT EXISTS outlet_event (
110	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
111	    outlet_code     VARCHAR(64)  NOT NULL,
112	    event_type      VARCHAR(40)  NOT NULL,
113	    event_time      TIMESTAMP    NOT NULL,
114	    late_flag       BOOLEAN      NOT NULL DEFAULT FALSE,
115	    payload         CLOB
116	);
117	COMMENT ON COLUMN outlet_event.event_type IS '事件类型：REGISTER/READING/MARK/ORDER_ISSUED/CONFIRM/ESCALATE/RELEASE/ARCHIVE/LATE_READING/GAP_SUPERVISE';
118	COMMENT ON COLUMN outlet_event.late_flag IS '是否归档后迟到事件；归档后迟到监测数据只记迟到事件不参与评价';
119	
120	CREATE TABLE IF NOT EXISTS idempotent_request (
121	    request_id      VARCHAR(80)  NOT NULL,
122	    request_type    VARCHAR(32)  NOT NULL,
123	    fingerprint     VARCHAR(64)  NOT NULL,
124	    result_json     CLOB         NOT NULL,
125	    created_at      TIMESTAMP    NOT NULL,
126	    CONSTRAINT pk_idempotent_request PRIMARY KEY (request_id)
127	);
128	COMMENT ON COLUMN idempotent_request.fingerprint IS '请求指纹：SHA-256( requestId + 全部业务字段 )，同键同参回放首次结果，同键异参返回 409';
129	
130	-- ================= 雨季溢流证据与双口径统计（cems-02 新增，合成数据，不用于生产） =================
131	-- 溢流证据独立留痕：原排放浓度读数、超标链与限排令记录不因溢流标记而改变。
132	
133	CREATE TABLE IF NOT EXISTS overflow_permit (
134	    id                  BIGINT AUTO_INCREMENT PRIMARY KEY,
135	    outlet_code         VARCHAR(64)  NOT NULL,
136	    version             INT          NOT NULL,
137	    window_start_utc    TIMESTAMP    NOT NULL,
138	    window_end_utc      TIMESTAMP    NOT NULL,
139	    min_rainfall_mm     DECIMAL(18,4) NOT NULL,
140	    max_consecutive_hours INT        NOT NULL,
141	    status              VARCHAR(16)  NOT NULL,
142	    created_at          TIMESTAMP    NOT NULL,
143	    CONSTRAINT uk_overflow_permit_version UNIQUE (outlet_code, version)
144	);
145	COMMENT ON COLUMN overflow_permit.outlet_code IS '排口编码，关联 discharge_outlet.outlet_code';
146	COMMENT ON COLUMN overflow_permit.version IS '许可版本号：从 1 开始，每次成功变更加 1；同排口内唯一';
147	COMMENT ON COLUMN overflow_permit.window_start_utc IS 'UTC 半开适用窗口起点（含本时刻），秒级精确时刻';
148	COMMENT ON COLUMN overflow_permit.window_end_utc IS 'UTC 半开适用窗口终点（不含本时刻）';
149	COMMENT ON COLUMN overflow_permit.min_rainfall_mm IS '最低小时雨量门槛，单位 mm；恰等门槛合法';
150	COMMENT ON COLUMN overflow_permit.max_consecutive_hours IS '允许的最大连续溢流小时数；连续段严格超过即专项异常';
151	COMMENT ON COLUMN overflow_permit.status IS '许可状态：ACTIVE 现行 / SUPERSEDED 已被新版本取代';
152	COMMENT ON COLUMN overflow_permit.created_at IS '创建时刻（Asia/Shanghai 本地时间，由应用时钟写入）';
153	
154	CREATE TABLE IF NOT EXISTS overflow_hour (
155	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
156	    outlet_code     VARCHAR(64)  NOT NULL,
157	    hour_utc        TIMESTAMP    NOT NULL,
158	    rainfall_mm     DECIMAL(18,4),
159	    overflow_flag   BOOLEAN      NOT NULL,
160	    avg_value       DECIMAL(18,4) NOT NULL,
161	    mark_status     VARCHAR(16)  NOT NULL,
162	    permit_version  INT,
163	    created_at      TIMESTAMP    NOT NULL,
164	    updated_at      TIMESTAMP    NOT NULL,
165	    CONSTRAINT uk_overflow_hour UNIQUE (outlet_code, hour_utc)
166	);
167	COMMENT ON COLUMN overflow_hour.hour_utc IS 'UTC 整点时刻（分秒必须为 0），排口＋整点唯一';
168	COMMENT ON COLUMN overflow_hour.rainfall_mm IS '该小时雨量，单位 mm；NULL 表示缺雨量（只能待核，不当零也不豁免）';
169	COMMENT ON COLUMN overflow_hour.overflow_flag IS '该小时是否发生溢流（合成标记）';
170	COMMENT ON COLUMN overflow_hour.avg_value IS '该小时排放浓度均值，单位 mg/L（合成数据）；原浓度记录永远保留';
171	COMMENT ON COLUMN overflow_hour.mark_status IS '溢流标记状态：PENDING 待核（缺雨量）/ COMPLIANT 合规溢流（证据齐全）/ NORMAL 非合规溢流或普通小时';
172	COMMENT ON COLUMN overflow_hour.permit_version IS '判定合规溢流时所用许可版本；非合规标记为 NULL';
173	COMMENT ON COLUMN overflow_hour.created_at IS '创建时刻（Asia/Shanghai 本地时间）';
174	COMMENT ON COLUMN overflow_hour.updated_at IS '最近更新时刻（Asia/Shanghai 本地时间）';
175	
176	CREATE TABLE IF NOT EXISTS overflow_counter (
177	    outlet_code      VARCHAR(64) PRIMARY KEY,
178	    rainfall_version INT          NOT NULL,
179	    updated_at       TIMESTAMP    NOT NULL
180	);
181	COMMENT ON COLUMN overflow_counter.rainfall_version IS '雨量版本号：首次上报小时数据置 1，每次成功雨量更正/调差加 1；无记录表示尚无雨量数据';
182	COMMENT ON COLUMN overflow_counter.updated_at IS '最近变更时刻（Asia/Shanghai 本地时间）';
183	
184	CREATE TABLE IF NOT EXISTS overflow_review (
185	    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
186	    outlet_code      VARCHAR(64)  NOT NULL,
187	    day_utc          DATE         NOT NULL,
188	    permit_version   INT,
189	    rainfall_version INT          NOT NULL,
190	    normal_avg       DECIMAL(18,4),
191	    normal_count     INT          NOT NULL,
192	    all_avg          DECIMAL(18,4),
193	    all_count        INT          NOT NULL,
194	    missing_count    INT          NOT NULL,
195	    status           VARCHAR(16)  NOT NULL,
196	    frozen_at        TIMESTAMP    NOT NULL,
197	    request_id       VARCHAR(80),
198	    CONSTRAINT uk_overflow_review UNIQUE (outlet_code, day_utc)
199	);
200	COMMENT ON COLUMN overflow_review.day_utc IS 'UTC 日结日期；同排口每日仅可冻结一次';
201	COMMENT ON COLUMN overflow_review.permit_version IS '冻结时现行溢流许可版本；无许可为 NULL';
202	COMMENT ON COLUMN overflow_review.rainfall_version IS '冻结时雨量版本号；无雨量数据记 0';
203	COMMENT ON COLUMN overflow_review.normal_avg IS '正常排放均值（mg/L）：仅排除证据齐全的合规溢流小时；空集合为 NULL（无结果而非零）';
204	COMMENT ON COLUMN overflow_review.normal_count IS '正常排放口径分母（计入小时数）';
205	COMMENT ON COLUMN overflow_review.all_avg IS '全部排放均值（mg/L）：不排除任何已上报小时；空集合为 NULL';
206	COMMENT ON COLUMN overflow_review.all_count IS '全部排放口径分母（计入小时数）';
207	COMMENT ON COLUMN overflow_review.missing_count IS '当日缺点数：UTC 日内无小时数据的整点数';
208	COMMENT ON COLUMN overflow_review.status IS '快照状态：FROZEN 已冻结（冻结后只能独立调差，不改本快照）';
209	COMMENT ON COLUMN overflow_review.frozen_at IS '冻结时刻（Asia/Shanghai 本地时间）';
210	COMMENT ON COLUMN overflow_review.request_id IS '冻结请求的幂等键';
211	
212	CREATE TABLE IF NOT EXISTS overflow_adjustment (
213	    id               BIGINT AUTO_INCREMENT PRIMARY KEY,
214	    outlet_code      VARCHAR(64)  NOT NULL,
215	    day_utc          DATE         NOT NULL,
216	    hour_utc         TIMESTAMP    NOT NULL,
217	    old_rainfall_mm  DECIMAL(18,4),
218	    new_rainfall_mm  DECIMAL(18,4) NOT NULL,
219	    rainfall_version INT          NOT NULL,
220	    request_id       VARCHAR(80),
221	    created_at       TIMESTAMP    NOT NULL
222	);
223	COMMENT ON COLUMN overflow_adjustment.day_utc IS '所属已冻结 UTC 日结日期';
224	COMMENT ON COLUMN overflow_adjustment.hour_utc IS '被调差的 UTC 整点';
225	COMMENT ON COLUMN overflow_adjustment.old_rainfall_mm IS '调差前雨量（mm）；NULL 表示原缺雨量';
226	COMMENT ON COLUMN overflow_adjustment.new_rainfall_mm IS '调差后雨量（mm）';
227	COMMENT ON COLUMN overflow_adjustment.rainfall_version IS '本次调差后的雨量版本号';
228	COMMENT ON COLUMN overflow_adjustment.request_id IS '调差请求的幂等键';
229	COMMENT ON COLUMN overflow_adjustment.created_at IS '调差登记时刻（Asia/Shanghai 本地时间）；独立调差不改日结快照';
230	
231	CREATE TABLE IF NOT EXISTS overflow_anomaly (
232	    id                BIGINT AUTO_INCREMENT PRIMARY KEY,
233	    outlet_code       VARCHAR(64)  NOT NULL,
234	    segment_start_utc TIMESTAMP    NOT NULL,
235	    segment_end_utc   TIMESTAMP    NOT NULL,
236	    hour_count        INT          NOT NULL,
237	    max_allowed       INT          NOT NULL,
238	    permit_version    INT          NOT NULL,
239	    reason            VARCHAR(255) NOT NULL,
240	    status            VARCHAR(16)  NOT NULL,
241	    created_at        TIMESTAMP    NOT NULL,
242	    CONSTRAINT uk_overflow_anomaly UNIQUE (outlet_code, segment_start_utc, segment_end_utc)
243	);
244	COMMENT ON COLUMN overflow_anomaly.segment_start_utc IS '连续合规溢流段起点（UTC 整点，含）；跨许可版本或出现缺点必须断段';
245	COMMENT ON COLUMN overflow_anomaly.segment_end_utc IS '连续合规溢流段终点（UTC 整点，不含）';
246	COMMENT ON COLUMN overflow_anomaly.hour_count IS '该连续段小时数（严格超过许可最长连续小时数才登记）';
247	COMMENT ON COLUMN overflow_anomaly.max_allowed IS '判定所用许可允许的最大连续溢流小时数';
248	COMMENT ON COLUMN overflow_anomaly.permit_version IS '该段所用溢流许可版本';
249	COMMENT ON COLUMN overflow_anomaly.reason IS '专项异常原因说明';
250	COMMENT ON COLUMN overflow_anomaly.status IS '异常状态：OPEN 待处置 / CLOSED 已处置';
251	COMMENT ON COLUMN overflow_anomaly.created_at IS '登记时刻（Asia/Shanghai 本地时间）';
252

