132	    private HourReportResult doReportHours(HourReportRequest req) {
133	        String code = requireText(req.outletCode(), "outletCode");
134	        loadOutlet(code);
135	        if (req.hours() == null || req.hours().isEmpty()) {
136	            throw new IllegalArgumentException("hours 不能为空集合");
137	        }
138	        Map<String, Boolean> seen = new LinkedHashMap<>();
139	        for (OverflowHourItem item : req.hours()) {
140	            validateHourItem(item);
141	            String key = item.hourUtc().toString();
142	            if (seen.put(key, Boolean.TRUE) != null) {
143	                throw new IllegalArgumentException("hours 内存在重复 UTC 整点: " + key);
144	            }
145	        }
146	        List<OverflowHourItem> items = new ArrayList<>(req.hours());
147	        items.sort(Comparator.comparing(OverflowHourItem::hourUtc));
148	        cemsRepo.lockOutlet(code);
149	        LocalDateTime now = clock.now();
150	        repo.ensureCounter(code, now);
151	        int reported = 0;
152	        int deduplicated = 0;
153	        List<HourMarkView> views = new ArrayList<>();
154	        for (OverflowHourItem item : items) {
155	            LocalDateTime hourUtc = toUtcLdt(item.hourUtc());
156	            Map<String, Object> existing = repo.findHour(code, hourUtc);
157	            if (existing != null) {
158	                // 排口＋整点去重：同参去重，异参 409；雨量更正须走更正入口。
159	                if (sameHourData(existing, item)) {
160	                    views.add(toHourMarkView(existing, true));
161	                    deduplicated++;
162	                    continue;
163	                }
164	                throw new ConflictException("排口＋UTC 整点小时数据已存在且内容不同: " + code + " " + item.hourUtc());
165	            }
166	            MarkDecision decision = evaluateNewHour(code, item, hourUtc);
167	            repo.insertHour(code, hourUtc, item.rainfallMm(), item.overflowFlag(), item.avgValue(),
168	                    decision.markStatus(), decision.permitVersion(), now);
169	            reported++;
170	            views.add(new HourMarkView(item.hourUtc(), decision.markStatus(), decision.permitVersion(),
171	                    item.rainfallMm(), item.overflowFlag(), item.avgValue(), false));
172	        }
173	        rebuildSegments(code);
