            boolean backfillFirst = review.countedCount() == 1
                    && review.effectiveAvg().compareTo(new BigDecimal("30.0000")) == 0
                    && "MACHINE".equals(review.items().get(0).source())
                    && review.items().get(0).replacementVersion() == null;
